mapper.select:
select tp.id, tp.organization_id, tp.version, tp.status, tp.expire_time, tp.remark, tp.create_time, tp.update_time, o.name as org_name, o.org_type, o.is_demo as demo, (select u.phone from sys_user u where u.last_organization_id = tp.organization_id limit 1) as phone, (select exists(select 1 from sys_organization_user ou where ou.user_id = (select u2.id from sys_user u2 where u2.last_organization_id = tp.organization_id limit 1) and ou.enable = 1)) as enabled, (select max(ll.create_time) from sys_login_log ll join sys_user u on u.id = ll.operator where u.last_organization_id = tp.organization_id) as last_login_time from tenant_plan tp join sys_organization o on o.id = tp.organization_id
and tp.version = #{request.version}
and tp.status = #{request.status}
and tp.status in ('ACTIVE', 'EXPIRED')
and (o.name like concat('%', #{request.keyword}, '%') or exists (select 1 from sys_user u2 where u2.last_organization_id = tp.organization_id and u2.phone like concat('%', #{request.keyword}, '%')))
order by tp.expire_time asc
